def solve(n, edges):
    # Initialize adjacency list
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n
    count = 0

    for node in range(n):
        if not visited[node]:
            count += 1
            # BFS to mark all nodes in the component
            queue = [node]
            visited[node] = True
            while queue:
                current = queue.pop(0)
                for neighbor in graph[current]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append(neighbor)

    return count
```

